"""The Network read model against goldens generated by the OLD code (``python -m projectzero.ops.parity_network
goldens``): ``people.listing`` (every derived field, the sort and its ties), ``ecosys.talent_tree`` (cycle, shared
descendant, depth limit, raising link types), the watchlist, the old tables and ``_slug``, at two clocks."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pytest

from projectzero.ops.parity_network import CLOCKS, diff, goldens_input, new_goldens

GOLDEN: dict[str, Any] = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_network.json").read_text(encoding="utf-8")
)
NEW = new_goldens(GOLDEN["input"])
SETS = [s["name"] for s in GOLDEN["input"]["sets"]]


def test_provenance_is_the_clean_old_revision() -> None:
    assert GOLDEN["provenance"]["old_revision"] == "6c739b9cb6ca2517b845e381d39a36c50eccc59e"
    assert GOLDEN["provenance"]["old_dirty"] is False
    assert GOLDEN["provenance"]["clocks"] == list(CLOCKS)


def test_the_golden_input_is_the_current_corpus() -> None:
    """The corpus in code and the one the oracle saw are the same (no silent drift of the test set)."""
    assert json.loads(json.dumps(goldens_input())) == GOLDEN["input"]


@pytest.mark.parametrize("name", SETS)
@pytest.mark.parametrize("clock", CLOCKS)
@pytest.mark.parametrize("part", ["listing", "tree", "watchlist"])
def test_every_set_matches_the_old_code(name: str, clock: str, part: str) -> None:
    assert diff(GOLDEN["expected"]["sets"][name][clock][part], NEW["sets"][name][clock][part]) == []


@pytest.mark.parametrize("section", ["strengths", "potential", "fields", "slugs"])
def test_tables_and_slug_match_the_old_code(section: str) -> None:
    assert diff(GOLDEN["expected"][section], NEW[section]) == []


def _listing(name: str, clock: str) -> list[dict[str, Any]]:
    return list(GOLDEN["expected"]["sets"][name][clock]["listing"]["ok"])


def test_the_corpus_pins_the_due_boundary_and_the_clock() -> None:
    first, second = (({p["id"]: p for p in _listing("dates", c)}) for c in CLOCKS)
    assert first["p-due-today"]["due"] is True  # next_action_date == today
    assert first["p-due-tomorrow"]["due"] is False and second["p-due-tomorrow"]["due"] is True  # past midnight
    assert first["p-no-date"]["due"] is True and first["p-null-date"]["due"] is True  # missing / None: due
    assert first["p-bad-date"]["due"] is False and first["p-int-date"]["due"] is False  # unparseable: not due
    assert first["p-touch-today"]["days_since_touch"] == 0 and second["p-touch-today"]["days_since_touch"] == 1
    assert first["p-touch-future"]["days_since_touch"] == -3
    assert first["p-touch-garbage"]["days_since_touch"] is None
    assert "p-no-id" not in first and len(first) == len(GOLDEN["input"]["sets"][0]["doc"]["people"]) - 3


def test_the_corpus_pins_stable_ties() -> None:
    ids = [p["id"] for p in _listing("ties", CLOCKS[0])]
    assert ids == ["p-tie-due-4", "p-tie-due-3", "p-tie-due-2", "p-tie-due-1", "p-new-due", "p-tie-none-3",
                   "p-tie-none-2", "p-tie-none-1", "p-new-zed", "p-new-amy", "p-tie-mid", "p-tie-mid-b"]  # fmt: skip


def test_the_corpus_pins_the_graph_shapes() -> None:
    forest = GOLDEN["expected"]["sets"]["graph"][CLOCKS[0]]["tree"]["ok"]

    def ids(nodes: list[dict[str, Any]]) -> list[Any]:
        return [[n["id"], ids(n["children"])] for n in nodes]

    roots = {n["id"]: n for n in forest}
    assert set(roots) == {"p-root-a", "p-root-b", "p-free", "p-depth-0"}  # cycles, self-introductions: no root
    assert ids(roots["p-root-a"]["children"]) == [["p-kid-1", [["p-shared", []]]], ["p-kid-2", []]]  # drawn once
    assert ["p-shared", []] in ids(roots["p-root-b"]["children"])  # ... but once per root
    depth, n = 0, roots["p-depth-0"]
    while n["children"]:
        depth, n = depth + 1, n["children"][0]
    assert depth == 6  # depth 0..6
    chain = {p["id"]: p["chain"] for p in _listing("graph", CLOCKS[0])}
    assert len(chain["p-depth-9"]) == 6 and chain["p-cyc-1"] == ["Cycle Two"]
    assert GOLDEN["expected"]["sets"]["quirks"][CLOCKS[0]]["tree"] == {"raises": "TypeError"}
